import {parseNames, chooseIndex, cents, money, localNow, deadline, schedule, obligation, periodTotals, groupTotals, validatePayment, validatePayout} from './engine.js';
import {openReport} from './report.js';
import {cloudInfo,configure,login,logout,readRemote,writeRemote,probeConnection} from './cloud.js';
import {createAutoSync} from './auto-sync.js';
const $=id=>document.getElementById(id);
const escape=text=>String(text??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<svg class="icon" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const uid=()=>crypto.randomUUID();
const validId = id => typeof id === 'string' && /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i.test(id);
const storageKey='pasanaku-digital-v2';
const emptyDB=()=>({schema:2,groups:[],active:null});
const deviceKey='pasanaku-device-v3';
let db=emptyDB(),storageProblem=false,deviceRaw=null,syncDoc=null,sync,tabStale=false;
try {
 deviceRaw=localStorage.getItem(deviceKey);
 if(deviceRaw) {
   syncDoc=JSON.parse(deviceRaw);validateBackup(syncDoc.data);
   if((syncDoc.owner!==null&&typeof syncDoc.owner!=='string') || (syncDoc.version!==null&&(!Number.isSafeInteger(syncDoc.version)||syncDoc.version<0)) || typeof syncDoc.dirty!=='boolean') throw Error('Metadatos de guardado inválidos.');
   db=syncDoc.data;
 } else {
   const saved=JSON.parse(localStorage.getItem(storageKey)||'null');
   if(saved){validateBackup(saved);db=saved;}
 }
} catch {syncDoc=null;storageProblem=true;}
syncDoc ||= {data:db,owner:null,version:null,dirty:db.groups.length>0};
let view='overview',periodId=null,search='',spinning=false,angle=0,toastTimer;
const routes=[['overview','Resumen','grid'],['people','Participantes','users'],['draw','Sorteo transparente','wheel'],['calendar','Calendario','calendar'],['payments','Aportes y pagos','wallet'],['fines','Fondo de multas','clock'],['reports','Reportes','file'],['settings','Respaldo y conexión','file']];
const group=()=>db.groups.find(g=>g.id===db.active);
const person=(g,id)=>g.people.find(p=>p.id===id);
const selected=g=>g.periods.find(p=>p.id===periodId)||g.periods.find(p=>!p.payout)||g.periods.at(-1);
const formatDate=(date,options={day:'numeric',month:'short',year:'numeric'})=>new Intl.DateTimeFormat('es-BO',{...options,timeZone:'America/La_Paz'}).format(new Date(date.includes('T')?date:date+'T12:00:00-04:00'));
const initials=name=>name.split(/\s+/).filter(Boolean).slice(0,2).map(n=>n[0]).join('').toUpperCase();
const avatar=(name,i=0)=>`<span class="avatar" style="background:${['#eaf0df','#e9edf5','#f8eddf','#eee9f5'][i%4]}">${escape(initials(name))}</span>`;
const button=(text,action,style='primary',attributes='')=>`<button class="button ${style}" data-action="${action}" ${attributes}>${text}</button>`;
const pill=(text,type='')=>`<span class="pill ${type}">${escape(text)}</span>`;
const empty=(title,text,action='')=>`<div class="empty"><span class="empty-icon">${icon('users')}</span><h3>${title}</h3><p>${text}</p>${action}</div>`;
function notify(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,6500);}
function persist(){sync.commit(db);storageProblem=false;}
function change(fn,text){if(tabStale){notify('Recarga esta pestaña antes de registrar cambios.');return false;}if(storageProblem&&!pendingImport){notify('Recupera un respaldo desde Respaldo y conexión antes de reemplazar datos que no se pudieron leer.');return false;}const before=structuredClone(db);try{fn();persist();render();if(text)notify(text);return true;}catch(error){db=before;const message=error.name==='QuotaExceededError'?'No se pudo guardar. Descarga un respaldo y libera espacio antes de continuar.':error.message;const node=$('modal').open?$('modal-content').querySelector('.form-error'):null;if(node)node.textContent=message;else notify(message);return false;}}
const audit=(g,text)=>g.audit.push({id:uid(),at:new Date().toISOString(),text});
function showModal(content,locked=false){$('modal-content').innerHTML=content;$('close-modal').hidden=locked;$('modal').dataset.locked=locked?'true':'false';if(!$('modal').open)$('modal').showModal();}
function closeModal(){if($('modal').dataset.locked!=='true')$('modal').close();}
$('close-modal').onclick=closeModal;
$('modal').addEventListener('cancel',event=>{if($('modal').dataset.locked==='true')event.preventDefault();});
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><div class="eyebrow">JUNTOS, TURNO A TURNO</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function groupBar(g){return `<div class="group-bar"><label class="select-group-label" for="group-select">Seleccionar grupo</label><select id="group-select" aria-label="Seleccionar grupo">${db.groups.map(x=>`<option value="${x.id}" ${x.id===g.id?'selected':''}>${escape(x.name)}</option>`).join('')}</select>${pill(g.periods.every(p=>p.payout)?'Ciclo entregado':g.order.length===g.people.length?'Sorteo completo':g.order.length?'Sorteo en curso':'Listo para sortear',g.order.length===g.people.length?'':'neutral')}</div>`;}
function stat(label,value,note,ic,accent=''){return `<div class="stat ${accent}"><div class="stat-head">${label}${icon(ic)}</div><strong>${value}</strong><small>${note}</small></div>`;}
function periodSelect(g,id='period-select'){const p=selected(g);return `<select id="${id}" aria-label="Seleccionar turno">${g.periods.map((r,i)=>`<option value="${r.id}" ${r.id===p.id?'selected':''}>Turno ${i+1} · ${escape(formatDate(r.date))}</option>`).join('')}</select>`;}
function setupHero(){return `<section class="hero"><div><div class="eyebrow">MENOS CUENTAS. MÁS TRANQUILIDAD.</div><h2>Tu pasanaku,<br>en buenas manos.</h2><p>Organiza los turnos, registra los aportes y mantén las cuentas claras. Todo en un solo lugar.</p>${button('＋ Crear mi primer pasanaku','create')}</div><div class="hero-art" aria-hidden="true"><div class="orbit"><span class="coin">Bs</span></div><span class="leaf">❧</span></div></section>`;}
function overview(g){
 if(!g)return heading('Unidos para avanzar.','Bienvenido. Hagamos más fácil organizar el ahorro de tu grupo.')+setupHero()+`<div class="stats">${stat('Participantes','0','Personas que ahorran juntas','users')}${stat('Fondo por turno',money(0),'El aporte de todos, para uno','wallet')}${stat('Aportes recibidos',money(0),'Todo registrado, todo claro','grid')}${stat('Fondo de multas',money(0),'Separado de los aportes','clock','accent')}</div><div class="grid-two"><section class="card"><div class="card-heading"><h2>Así de sencillo funciona</h2>${pill('3 pasos')}</div><ol class="rules-list"><li>Crea el grupo y acuerda monto, fechas y multas.</li><li>Sortea un turno para cada participante, sin preferencias.</li><li>Registra los pagos y la entrega de cada fondo.</li></ol><div class="notice"><p>Quien ya recibió su fondo <strong>sigue aportando hasta el último turno</strong>, igual que todos.</p></div></section><section class="card"><h2>Tu próximo desembolso</h2>${empty('Todo comienza con tu grupo.','Cuando lo crees, aquí verás la próxima fecha y el avance de los aportes.')}</section></div>`;
 const p=selected(g),t=periodTotals(g,p),tot=groupTotals(g),who=person(g,p.person),pot=g.amount*g.people.length;
 const index=g.periods.indexOf(p);
 const recent=g.payments.filter(r=>!r.voided).slice(-4).reverse();
 return heading('Cada aporte nos acerca.','Un vistazo a tu grupo, sus turnos y todo lo que viene.',button('＋ Nuevo pasanaku','create','secondary'))+groupBar(g)+`<section class="hero"><div><div class="eyebrow">${escape(g.name)}</div><h2>Un grupo. Una meta.<br>Las cuentas claras.</h2><p>${g.people.length} personas aportando ${money(g.amount)} ${g.frequency==='weekly'?'cada semana':g.frequency==='monthly'?'cada mes':'cada '+g.interval+' días'}. El fondo completo llega a una persona en cada turno.</p><button class="button primary" data-view="payments">Registrar un aporte ${icon('arrow')}</button></div><div class="hero-art" aria-hidden="true"><div class="orbit"><span class="coin">Bs</span></div><span class="leaf">❧</span></div></section><div class="stats">${stat('Participantes',g.people.length,'Todos aportan en cada turno','users')}${stat('Fondo por turno',money(pot),money(g.amount)+' por persona','wallet')}${stat('Aportes en caja',money(tot.principal-tot.disbursed),'Recibido menos desembolsado','grid')}${stat('Fondo de multas',money(tot.finePaid-tot.fineUsed),'Cobrado y aún no utilizado','clock','accent')}</div><div class="grid-two"><section class="card"><div class="card-heading"><div><h2>El próximo turno</h2><p class="subtext">Turno ${index+1} de ${g.people.length} · ${escape(formatDate(p.date))}</p></div>${pill(p.payout?'Entregado':deadline(p)<Date.now()?'Fecha cumplida':'Próximamente',p.payout?'':'warning')}</div><div class="next-recipient">${avatar(who?.name||'?')}<div><strong>${escape(who?.name||'Beneficiario por sortear')}</strong><p>${who?'Recibe el fondo de este turno':'Asigna su turno con la ruleta'}</p></div><div class="recipient-amount"><strong>${money(pot)}</strong><small>Fondo a entregar</small></div></div><div class="progress-info"><span>Aportes completos</span><strong>${t.complete} de ${g.people.length}</strong></div><div class="progress-track"><div class="progress-fill" style="width:${t.complete/g.people.length*100}%"></div></div><div class="card-foot"><p>${icon('clock')} Límite: ${p.time} · Hora de La Paz</p><button class="link-button" data-view="payments">Ver aportes ${icon('arrow')}</button></div></section><section class="card"><div class="card-heading"><h2>Últimos aportes</h2><button class="link-button" data-view="payments">Ver todos ${icon('arrow')}</button></div>${recent.length?`<ul class="mini-list">${recent.map((r,i)=>`<li>${avatar(person(g,r.person)?.name||'',i)}<div><strong>${escape(person(g,r.person)?.name)}</strong><small>${escape(r.method)} · ${escape(formatDate(r.at))}</small></div><div class="right"><strong>${money(r.principal+r.fine)}</strong><small>Verificado</small></div></li>`).join('')}</ul>`:empty('Aún no hay aportes.','Registra el primer pago en efectivo, QR o transferencia.')}</section></div><section class="card"><div class="card-heading"><h2>Un calendario para todos</h2><button class="link-button" data-view="calendar">Ver calendario ${icon('arrow')}</button></div>${calendarTable(g,4)}</section><div class="notice ${tot.overdue?'warning':''}">${icon('clock')}<p>${tot.overdue?`Hay <strong>${money(tot.overdue)}</strong> en aportes vencidos y <strong>${money(tot.fine-tot.finePaid)}</strong> de multas por cobrar. Revisa Aportes y pagos.`:`Todos siguen aportando hasta el final. Las multas se guardan en un fondo separado: <strong>${escape(g.fundDestination)}</strong>.`}</p></div>`;
}
function calendarTable(g,limit=g.periods.length){return `<div class="table-wrap"><table><thead><tr><th>Turno</th><th>Fecha de entrega</th><th>Participante</th><th>Fondo</th><th>Estado</th></tr></thead><tbody>${g.periods.slice(0,limit).map((p,i)=>`<tr><td><span class="tag-number">${String(i+1).padStart(2,'0')}</span></td><td>${escape(formatDate(p.date))}<small>Límite ${p.time}</small></td><td>${escape(person(g,p.person)?.name||'Por sortear')}</td><td>${money(g.amount*g.people.length)}</td><td>${pill(p.payout?'Entregado':p.person?'Asignado':'Por sortear',p.payout?'':p.person?'warning':'neutral')}</td></tr>`).join('')}</tbody></table></div>`;}
function peoplePage(g){return heading('Las personas, primero.','Todos tienen un turno. Todos aportan hasta el final.')+groupBar(g)+`<section class="card"><div class="card-heading"><h2>${g.people.length} participantes</h2>${pill('Lista fijada al crear el grupo','neutral')}</div><div class="table-wrap"><table><thead><tr><th>Participante</th><th>Turno y fecha</th><th>Aportes recibidos</th><th>Debe aporte vencido</th><th>Multas pendientes</th></tr></thead><tbody>${g.people.map((person,i)=>{const turn=g.periods.find(p=>p.person===person.id);const sums=g.periods.reduce((s,p)=>{const o=obligation(g,p,person);s.paid+=o.principal;s.debt+=deadline(p)<Date.now()?o.owed:0;s.fine+=o.fineOwed;return s;},{paid:0,debt:0,fine:0});return `<tr><td><div class="person">${avatar(person.name,i)}<strong>${escape(person.name)}</strong></div></td><td>${turn?`Turno ${g.periods.indexOf(turn)+1}<small>${escape(formatDate(turn.date))}</small>`:'Por sortear'}</td><td>${money(sums.paid)}</td><td>${money(sums.debt)}</td><td>${money(sums.fine)}</td></tr>`;}).join('')}</tbody></table></div></section><div class="notice">${icon('users')}<p>La lista y los acuerdos se fijan al crear el grupo para no cambiar las obligaciones durante el ciclo. Si hay un error y aún no hubo sorteos ni movimientos, puedes eliminar el grupo desde Respaldo y conexión y crearlo de nuevo.</p></div>`;}
function calendarPage(g){const current=selected(g);return heading('Cada turno, en su fecha.','El calendario completo de tu pasanaku, desde el primero hasta el último.',button(icon('file')+' Resumen / PDF','report-all','secondary'))+groupBar(g)+`<div class="timeline">${g.periods.map((p,i)=>{const t=periodTotals(g,p);return `<section class="turn-card ${p.id===current.id?'current':''}"><div class="turn-head"><span class="tag-number">${String(i+1).padStart(2,'0')}</span>${pill(p.payout?'Entregado':t.owed?'Aportes pendientes':'Fondo completo',p.payout?'':t.owed?'neutral':'')}</div><div class="turn-date">${escape(formatDate(p.date))}</div><p>Hasta las ${p.time} · La Paz</p><div class="person-name">${escape(person(g,p.person)?.name||'Beneficiario por sortear')}</div><p>${money(g.amount*g.people.length)} · ${t.complete}/${g.people.length} aportes completos</p><button class="button secondary full-width" data-action="turn" data-id="${p.id}">Ver este turno ${icon('arrow')}</button></section>`;}).join('')}</div>`;}
function drawPage(g){const remaining=g.people.filter(p=>!g.order.includes(p.id));const next=g.periods[g.order.length];return heading('Un sorteo para confiar.','Las mismas posibilidades para todos. Sin nombres favorecidos ni turnos reservados.')+groupBar(g)+`<div class="wheel-layout"><section class="card wheel-panel"><div class="wheel-stage"><div class="pointer" aria-hidden="true"></div><canvas id="wheel" width="900" height="900" aria-label="Ruleta de participantes pendientes"></canvas><div class="wheel-center" aria-hidden="true">✳</div></div>${button(icon('wheel')+(g.pending?' Ver resultado pendiente':remaining.length?' Girar la ruleta':' Sorteo completo'),g.pending?'pending':'spin','primary',remaining.length&&!spinning?'':'disabled')}<p>${remaining.length} participantes pendientes ${next?'· Turno '+(g.order.length+1)+' · '+escape(formatDate(next.date)):''}</p></section><div><section class="card"><div class="card-heading"><h2>El orden de los turnos</h2>${pill(g.order.length+' de '+g.people.length,'neutral')}</div>${g.order.length?`<ul class="mini-list">${g.order.map((id,i)=>`<li><span class="tag-number">${i+1}</span><div><strong>${escape(person(g,id)?.name)}</strong><small>${escape(formatDate(g.periods[i].date))}</small></div></li>`).join('')}</ul>`:empty('El primer turno te espera.','Cada nombre aceptado se retira de la ruleta y recibe la próxima fecha.')}</section><div class="notice"><p>El resultado se guarda <strong>antes de la animación</strong>. Recargar la página no permite volver a sortearlo. Al aceptar, el turno queda asignado en el calendario.</p></div><section class="card"><h2>Cómo se elige</h2><p>Se usa el generador criptográfico del navegador y una selección uniforme entre los nombres restantes. La ruleta se detiene en el resultado guardado.</p><p class="subtext">El historial permite revisar las asignaciones. Esta versión no es una certificación externa del sorteo.</p></section></div></div>`;}
function statusBadge(o){return o.owed?pill(o.principal?'Abono parcial':o.late?'Vencido':'Pendiente',o.late?'red':'warning'):pill(o.fineOwed?'Aporte completo · debe multa':'Al día',o.fineOwed?'warning':'');}
function paymentRows(g,p){return g.people.filter(x=>x.name.toLowerCase().includes(search.toLowerCase())).map((person,i)=>{const o=obligation(g,p,person);return `<tr><td><div class="person">${avatar(person.name,i)}<div><strong>${escape(person.name)}</strong>${p.person===person.id?'<small>Recibe este turno · también aporta</small>':''}</div></div></td><td data-label="Aportado">${money(o.principal)}<small>de ${money(g.amount)}</small></td><td data-label="Debe aporte">${money(o.owed)}</td><td data-label="Debe multa">${money(o.fineOwed)}${o.waiver?'<small>Multa condonada</small>':''}</td><td data-label="Estado">${statusBadge(o)}</td><td>${button('Registrar','payment','soft small',`data-person="${person.id}"`)}</td></tr>`;}).join('');}
function paymentsPage(g){const p=selected(g),t=periodTotals(g,p);const who=person(g,p.person);return heading('Cada aporte cuenta.','Registra el dinero recibido. Los abonos y las multas quedan separados.')+groupBar(g)+`<div class="toolbar">${periodSelect(g)}<input id="search" type="search" aria-label="Buscar participante" placeholder="Buscar participante…" value="${escape(search)}"></div><div class="notice">${icon('wallet')}<p>Registra QR o transferencia <strong>solo después de verificar el depósito en tu cuenta</strong>. El sistema lleva el control; no mueve dinero ni confirma operaciones bancarias.</p></div><div class="stats">${stat('Fondo esperado',money(g.amount*g.people.length),g.people.length+' aportes de '+money(g.amount),'users')}${stat('Recibido este turno',money(t.principal),t.complete+' aportes completos','wallet')}${stat('Falta recaudar',money(t.owed),'Solo aportes, sin multas','clock')}${stat('Multas cobradas',money(t.finePaid),money(t.fineOwed)+' por cobrar','grid','accent')}</div><section class="card"><div class="card-heading"><h2>Control de aportes</h2>${button(icon('file')+' PDF del turno','report-period','secondary small')}</div><div class="table-wrap"><table class="payment-table"><thead><tr><th>Participante</th><th>Aportado</th><th>Debe aporte</th><th>Debe multa</th><th>Estado</th><th>Acción</th></tr></thead><tbody id="payment-rows">${paymentRows(g,p)}</tbody></table></div></section><section class="card"><div class="next-recipient">${avatar(who?.name||'?')}<div><strong>${escape(who?.name||'Beneficiario por sortear')}</strong><p>${p.payout?'Entrega registrada el '+escape(formatDate(p.payout.at)):'Fondo de este turno · '+money(g.amount*g.people.length)}</p></div><div class="spacer"></div>${button(p.payout?'Entregado':'Registrar entrega','payout',p.payout?'soft':'primary',p.payout||!who||t.owed?'disabled':'')}</div><p class="subtext">La entrega se habilita al asignar un beneficiario y completar todos los aportes del turno. Registrar una entrega no ejecuta una transferencia.</p></section><section class="card"><div class="card-heading"><h2>Movimientos del turno</h2><span class="saved-note">Los errores se anulan, no se borran.</span></div>${movementTable(g,p)}</section>`;}
function movementTable(g,p){const records=g.payments.filter(r=>r.period===p.id).slice().reverse();return records.length?`<div class="table-wrap"><table><thead><tr><th>Fecha real</th><th>Participante</th><th>Aporte / multa</th><th>Medio y referencia</th><th>Acción</th></tr></thead><tbody>${records.map(r=>`<tr><td>${escape(formatDate(r.at))}<small>${escape(localNow(new Date(r.at)).slice(11))} · La Paz</small></td><td>${escape(person(g,r.person)?.name)}${r.note?'<small>'+escape(r.note)+'</small>':''}</td><td>${money(r.principal)}<small>Multa: ${money(r.fine)}</small></td><td>${escape(r.method)}<small>${escape(r.reference||'Sin referencia')}</small></td><td>${r.voided?pill('Anulado','neutral')+`<small>${escape(r.voided.reason)}</small>`:button('Anular','void-payment','danger small',`data-id="${r.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Sin movimientos en este turno.','Los aportes que registres aparecerán aquí.');}
function finesPage(g){const tot=groupTotals(g),debts=[];for(const p of g.periods)for(const person of g.people){const o=obligation(g,p,person);if(o.fine||o.waiver)debts.push({p,person,o});}return heading('Un fondo, con propósito.','Las multas tienen su propia cuenta y su propio destino.')+groupBar(g)+`<div class="stats">${stat('Multas aplicadas',money(tot.fine),'Una multa fija por cuota atrasada','clock')}${stat('Multas cobradas',money(tot.finePaid),'Dinero realmente recibido','wallet')}${stat('Por cobrar',money(tot.fine-tot.finePaid),'No forma parte de la caja','file')}${stat('Fondo disponible',money(tot.finePaid-tot.fineUsed),'Cobrado menos utilizado','grid','accent')}</div><div class="notice">${icon('users')}<p><strong>Destino acordado:</strong> ${escape(g.fundDestination)}<br>Multa fija: ${money(g.fine)} por cuota incompleta después de las ${g.time} de cada fecha. No se acumula diariamente. Las condonaciones exigen un motivo y quedan en el historial.</p></div><section class="card"><div class="card-heading"><h2>Detalle de multas</h2></div>${debts.length?`<div class="table-wrap"><table><thead><tr><th>Persona</th><th>Turno</th><th>Aplicada</th><th>Pagada</th><th>Pendiente</th><th>Acción</th></tr></thead><tbody>${debts.map(({p,person,o})=>`<tr><td>${escape(person.name)}</td><td>${g.periods.indexOf(p)+1}<small>${escape(formatDate(p.date))}</small></td><td>${money(o.fine)}</td><td>${money(o.finePaid)}</td><td>${money(o.fineOwed)}</td><td>${o.waiver?pill('Condonada','neutral'):`${button('Cobrar','payment','soft small',`data-person="${person.id}" data-period="${p.id}"`)} ${button('Condonar','waive','secondary small',`data-person="${person.id}" data-period="${p.id}" ${o.finePaid?'disabled':''}`)}`}</td></tr>`).join('')}</tbody></table></div>`:empty('Sin multas por ahora.','Aquí aparecerán automáticamente las cuotas que pasen de la hora límite.')}</section><section class="card"><div class="card-heading"><h2>Uso del fondo de multas</h2>${button('＋ Registrar uso','fund-use','primary small',tot.finePaid<=tot.fineUsed?'disabled':'')}</div>${g.fundUses.length?`<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Destino y motivo</th><th>Monto</th></tr></thead><tbody>${g.fundUses.map(r=>`<tr><td>${escape(formatDate(r.at))}</td><td>${escape(r.reason)}</td><td>${money(r.amount)}</td></tr>`).join('')}</tbody></table></div>`:empty('El fondo sigue intacto.','Registra aquí su distribución o el gasto que el grupo acuerde. Los aportes de los turnos no se mezclan con este fondo.')}</section>`;}
function reportsPage(g){return heading('Las cuentas, a la vista.','Un resumen sencillo para revisar y compartir con tu grupo.')+groupBar(g)+`<section class="card"><div class="report-options"><div class="report-box">${icon('calendar')}<h2>Resumen de un turno</h2><p>Aportes de cada persona, abonos, multas, saldo pendiente y entrega del fondo. Úsalo para tu cierre semanal o mensual.</p>${periodSelect(g)}<br><br>${button(icon('file')+' Preparar PDF del turno','report-period')}</div><div class="report-box">${icon('file')}<h2>Resumen del ciclo completo</h2><p>Calendario sorteado, todas las cuotas, multas, desembolsos y uso del fondo. Incluye acuerdos y registro de cambios.</p><br>${button(icon('file')+' Preparar PDF del ciclo','report-all','secondary')}</div></div><p class="subtext" style="margin-top:20px">Se muestra un informe listo para imprimir. Pulsa «Imprimir / Guardar como PDF» y elige «Guardar como PDF». No se envía automáticamente a nadie.</p></section><section class="card"><div class="card-heading"><h2>Historial de administración</h2>${button('Descargar respaldo','backup','secondary small')}</div>${g.audit.slice().reverse().map(a=>`<div class="audit-line">${escape(a.text)}<small>${escape(localNow(new Date(a.at)).replace('T',' '))} · ${escape(g.admin)}</small></div>`).join('')}</section>`;}
function settingsPage(g){const c=cloudInfo();return heading('Tus datos, bien cuidados.','Guarda un respaldo o conecta tu espacio con Supabase.')+`<div class="notice ${storageProblem?'warning':''}">${icon('file')}<p><strong>${storageProblem?'No se pudo leer el guardado local. No registres cambios hasta recuperar un respaldo.':c.connected?'Guardado automático activado.':'Guardado en este dispositivo.'}</strong> Los datos actuales están en este navegador. ${c.connected?'Cada cambio se guarda automáticamente en Supabase. Si no hay conexión, queda pendiente en este dispositivo.':'Inicia sesión para activar el guardado automático en Supabase.'} Descarga respaldos periódicos.</p></div><div class="grid-two"><section class="card"><h2>Un respaldo que puedes llevar contigo</h2><p>Incluye todos tus grupos, acuerdos, turnos, pagos e historial. Guárdalo en un lugar privado.</p><div class="actions">${button('↓ Descargar respaldo','backup')}${button('Restaurar respaldo','import','secondary')}</div><div class="divider"></div><h2>Tu conexión a Supabase</h2><p>Tu proyecto Pasanaku Digital ya está configurado. ${c.connected?'Tu sesión está activa. Tus grupos y movimientos se sincronizan automáticamente.':'Inicia sesión para cargar tus datos y guardarlos automáticamente.'}</p>${button('Verificar conexión','cloud-probe','secondary small')}<br><br><details><summary>Cambiar conexión (avanzado)</summary><br><form id="config-form"><div class="field"><label for="cloud-url">URL del proyecto</label><input id="cloud-url" type="url" required placeholder="https://tu-proyecto.supabase.co" value="${escape(c.url||'')}"></div><br><div class="field"><label for="cloud-key">Clave pública (publishable o anon)</label><input id="cloud-key" required type="password" autocomplete="off" value="${escape(c.key||'')}" placeholder="sb_publishable_…"><small>Nunca ingreses service_role ni claves secretas.</small></div><div class="form-actions"><button class="button secondary" type="submit">Guardar configuración</button></div><p class="form-error" id="config-error"></p></form></details></section><section class="card"><h2>Acceso del administrador</h2>${c.connected?`<p>Sesión de ${escape(c.email)}.</p><p id="cloud-status" aria-live="polite">${escape(sync?.status().message||'Comprobando tu copia…')}</p><div class="actions">${button('Revisar copia de la nube','cloud-load','secondary')}${button('Sincronizar ahora','cloud-push')}</div><br>${button('Cerrar sesión','logout','secondary small')}<p class="subtext" style="margin-top:18px">No necesitas pulsar ningún botón después de registrar cambios. Si aparece un conflicto, descarga un respaldo de tus cambios locales antes de cargar la copia de la nube.</p>`:`<p>Usa un usuario administrador creado en tu proyecto Supabase. Cada cuenta tiene su propio espacio privado.</p><form id="login-form"><div class="field"><label for="email">Correo</label><input id="email" type="email" required autocomplete="username"></div><br><div class="field"><label for="password">Contraseña</label><input id="password" type="password" required autocomplete="current-password"></div><div class="form-actions"><button class="button primary" type="submit">Iniciar sesión</button></div><p class="form-error" id="login-error"></p></form>`}<div class="divider"></div><h2>Reglas de este grupo</h2>${g?`<p><strong>${escape(g.name)}</strong> · Administra ${escape(g.admin)}<br>${escape(g.agreement)}<br>Multas: ${escape(g.fundDestination)}</p>${button('Eliminar grupo sin iniciar','delete-group','danger small',g.order.length||g.pending||g.payments.length||g.fundUses.length?'disabled':'')}`:'<p>Crea tu primer grupo para definir sus acuerdos.</p>'}</section></div>`;}
function render(){
 const g=group();$('navigation').innerHTML=routes.map(([key,label,ic])=>`<button class="nav-link ${view===key?'active':''}" data-view="${key}">${icon(ic)}${label}</button>`).join('');
 $('breadcrumb').textContent=`${g?.name||'Mi pasanaku'} / ${routes.find(r=>r[0]===view)?.[1]}`;
 $('today').textContent=formatDate(localNow().slice(0,10),{weekday:'short',day:'numeric',month:'long'});
 updateSyncUI();
 if(!g && view!=='settings')$('main').innerHTML=view==='overview'?overview():heading(routes.find(r=>r[0]===view)?.[1]||'Tu pasanaku','Primero definamos tu grupo y sus acuerdos.')+setupHero();
 else $('main').innerHTML=({overview,people:peoplePage,draw:drawPage,calendar:calendarPage,payments:paymentsPage,fines:finesPage,reports:reportsPage,settings:settingsPage}[view])(g);
 if(view==='draw'&&g)drawWheel(g,angle);
}
function createGroup(){showModal(`<div class="eyebrow">UN NUEVO COMIENZO</div><h2>Crea tu pasanaku</h2><p>Definan estos acuerdos entre todos antes de comenzar.</p><form id="group-form"><div class="form-grid"><div class="field"><label for="group-name">Nombre del grupo</label><input id="group-name" name="name" maxlength="70" required placeholder="Ej. Ahorro entre amigos"></div><div class="field"><label for="admin-name">Nombre del administrador</label><input id="admin-name" name="admin" maxlength="70" required placeholder="Tu nombre"></div><div class="field full"><label for="names">Participantes · uno por línea</label><textarea id="names" name="names" required placeholder="Ingresa los nombres aquí…"></textarea><small>Entre 2 y 100 personas. Inclúyete si también vas a participar. Usa nombres distintos para identificar a cada persona.</small></div><div class="field"><label for="amount">Aporte por persona (Bs)</label><input id="amount" name="amount" type="number" required min="0.01" max="1000000" step="0.01" placeholder="200.00"></div><div class="field"><label for="frequency">Frecuencia</label><select id="frequency" name="frequency"><option value="monthly">Mensual</option><option value="weekly">Semanal</option><option value="custom">Cada cierto número de días</option></select></div><div class="field" id="interval-field" hidden><label for="interval">Días entre turnos</label><input id="interval" name="interval" type="number" min="1" max="365" value="7"></div><div class="field"><label for="start">Primer desembolso</label><input id="start" name="start" type="date" value="${localNow().slice(0,10)}" required></div><div class="field"><label for="limit">Hora límite para aportar</label><input id="limit" name="time" type="time" value="18:00" required><small>Todos los horarios son de Bolivia (La Paz).</small></div><div class="field"><label for="fine">Multa por cuota atrasada (Bs)</label><input id="fine" name="fine" type="number" min="0" max="1000000" step="0.01" value="0" required><small>Fija, una vez por turno. Cero para no aplicar multas.</small></div><div class="field"><label for="fund-destination">Destino del fondo de multas</label><input id="fund-destination" name="fundDestination" maxlength="200" required placeholder="Ej. Repartir al cerrar el ciclo"></div><div class="field full"><label for="agreement">Otros acuerdos del grupo</label><textarea id="agreement" name="agreement" maxlength="1000" style="min-height:70px" placeholder="Ej. Cómo se harán las entregas y quién verificará los depósitos."></textarea></div><label class="check-label field full"><input type="checkbox" required>El grupo acordó el aporte, las fechas, las multas y su destino. Todos seguirán aportando después de recibir su fondo.</label></div><p class="form-error" id="group-error"></p><div class="form-actions"><button class="button primary" type="submit">Crear grupo y calendario ${icon('arrow')}</button></div></form>`);}
function submitGroup(form){const f=Object.fromEntries(new FormData(form));const names=parseNames(f.names);if(names.length<2||names.length>100)throw Error('Ingresa entre 2 y 100 participantes.');if(names.some(n=>n.length>100))throw Error('Cada nombre debe tener hasta 100 caracteres.');if(new Set(names.map(n=>n.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').toLowerCase())).size!==names.length)throw Error('Hay nombres repetidos. Añade apellidos para distinguirlos.');if(!f.name.trim()||!f.admin.trim()||!f.fundDestination.trim())throw Error('Completa el nombre del grupo, administrador y destino del fondo.');const amount=cents(f.amount);if(!amount)throw Error('El aporte debe ser mayor a cero.');const interval=Number(f.interval);if(!Number.isInteger(interval)||interval<1||interval>365)throw Error('Revisa los días entre turnos.');const dates=schedule(f.start,f.frequency,names.length,interval);if(dates.some(d=>d>'2100-12-31')||f.start<'2000-01-01')throw Error('Usa fechas entre 2000 y 2100.');const g={id:uid(),name:f.name.trim(),admin:f.admin.trim(),amount,fine:cents(f.fine),frequency:f.frequency,interval,time:f.time,fundDestination:f.fundDestination.trim(),agreement:f.agreement.trim(),people:names.map(name=>({id:uid(),name})),periods:dates.map(date=>({id:uid(),date,time:f.time,person:null,payout:null})),order:[],pending:null,payments:[],waivers:[],fundUses:[],audit:[],createdAt:new Date().toISOString()};audit(g,'Grupo creado. Aporte, participantes, calendario y reglas acordados.');if(change(()=>{db.groups.push(g);db.active=g.id;view='overview';periodId=null;},'Tu pasanaku está listo. Ya puedes sortear los turnos.'))$('modal').close();}
function paymentModal(personId,turnId){const g=group(),p=g.periods.find(r=>r.id===turnId)||selected(g),who=person(g,personId),o=obligation(g,p,who);showModal(`<h2>Registrar aporte</h2><p>${escape(who.name)} · Turno ${g.periods.indexOf(p)+1} · ${escape(formatDate(p.date))}</p><div class="balance-box"><div><span>Debe aporte</span><strong>${money(o.owed)}</strong></div><div><span>Debe multa</span><strong>${money(o.fineOwed)}</strong></div></div><form id="payment-form" data-person="${who.id}" data-period="${p.id}"><div class="form-grid"><div class="field"><label for="principal">Aporte recibido (Bs)</label><input id="principal" name="principal" type="number" min="0" step="0.01" value="${o.owed/100}" required></div><div class="field"><label for="paid-fine">Multa recibida (Bs)</label><input id="paid-fine" name="fine" type="number" min="0" step="0.01" value="0" required></div><div class="field"><label for="method">Medio de pago</label><select id="method" name="method"><option>QR</option><option>Efectivo</option><option>Transferencia</option></select></div><div class="field"><label for="payment-date">Fecha y hora real del pago</label><input id="payment-date" name="at" type="datetime-local" required max="${localNow()}" value="${localNow()}"><small>Hora de La Paz. Si se pagó a tiempo, indica ese momento para calcular correctamente la multa.</small></div><div class="field full"><label for="reference">Referencia / número de operación</label><input id="reference" name="reference" maxlength="120" placeholder="Obligatorio para QR o transferencia"></div><div class="field full"><label for="note">Nota (opcional)</label><input id="note" name="note" maxlength="250" placeholder="Ej. Primer abono de la cuota"></div><label class="check-label field full"><input type="checkbox" name="verified" required>Verifiqué que el dinero fue recibido. La referencia identifica el depósito; el sistema no lo valida con el banco.</label></div><p class="form-error" id="payment-error"></p><div class="form-actions"><button type="submit" class="button primary">Guardar aporte verificado</button></div></form>`);}
function submitPayment(form){const g=group(),p=g.periods.find(p=>p.id===form.dataset.period),who=person(g,form.dataset.person);const f=Object.fromEntries(new FormData(form));const r={id:uid(),period:p.id,person:who.id,principal:cents(f.principal),fine:cents(f.fine),at:new Date(f.at+':00-04:00').toISOString(),method:f.method,reference:f.reference.trim(),note:f.note.trim(),verified:Boolean(f.verified),recordedAt:new Date().toISOString()};validatePayment(g,p,who,r);if(change(()=>{g.payments.push(r);audit(g,`Pago de ${who.name}: aporte ${money(r.principal)}, multa ${money(r.fine)}. Turno ${g.periods.indexOf(p)+1}. ${r.method}.`);},'Aporte guardado y saldo actualizado.'))$('modal').close();}
function reasonModal(title,description,action,data){showModal(`<h2>${title}</h2><p>${description}</p><form id="reason-form" data-task="${action}" ${data}><div class="field"><label for="reason">Motivo del cambio</label><textarea id="reason" name="reason" required minlength="5" maxlength="300" placeholder="Explica el motivo para que quede en el historial."></textarea></div><p class="form-error" id="reason-error"></p><div class="form-actions"><button class="button primary" type="submit">Confirmar registro</button></div></form>`);}
function submitReason(form){const reason=new FormData(form).get('reason').trim();if(reason.length<5)throw Error('Escribe un motivo de al menos 5 caracteres.');const g=group();const task=form.dataset.task;if(change(()=>{if(task==='void'){const r=g.payments.find(r=>r.id===form.dataset.id),p=g.periods.find(p=>p.id===r.period);if(r.voided)throw Error('El registro ya está anulado.');if(p.payout&&r.principal)throw Error('El fondo ya fue entregado. No se puede anular un aporte que respalda esa entrega.');if(r.fine&&groupTotals(g).finePaid-r.fine<groupTotals(g).fineUsed)throw Error('Este dinero del fondo de multas ya se utilizó.');r.voided={at:new Date().toISOString(),reason};audit(g,`Anulado pago de ${person(g,r.person).name}, turno ${g.periods.indexOf(p)+1}: ${reason}`);}else if(task==='waive'){const p=g.periods.find(p=>p.id===form.dataset.period),who=person(g,form.dataset.person),o=obligation(g,p,who);if(o.finePaid||o.waiver||!o.fine)throw Error('Esta multa ya fue pagada, condonada o no corresponde.');g.waivers.push({id:uid(),period:p.id,person:who.id,reason,at:new Date().toISOString()});audit(g,`Multa condonada a ${who.name}, turno ${g.periods.indexOf(p)+1}: ${reason}`);}},'Cambio registrado en el historial.'))$('modal').close();}
function payoutModal(){const g=group(),p=selected(g),amount=validatePayout(g,p);showModal(`<h2>Registrar entrega del fondo</h2><p>Turno ${g.periods.indexOf(p)+1} · ${escape(person(g,p.person).name)}<br>Fondo completo: <strong>${money(amount)}</strong>. Este registro no transfiere dinero.</p><form id="payout-form" data-period="${p.id}"><div class="form-grid"><div class="field"><label for="delivery-method">Medio de entrega</label><select id="delivery-method" name="method"><option>Transferencia</option><option>QR</option><option>Efectivo</option></select></div><div class="field"><label for="delivery-date">Fecha y hora de entrega</label><input id="delivery-date" name="at" type="datetime-local" value="${localNow()}" max="${localNow()}" required></div><div class="field full"><label for="delivery-reference">Referencia o constancia de recepción</label><input id="delivery-reference" name="reference" required maxlength="160" placeholder="Operación bancaria o constancia de entrega en efectivo"></div><label class="check-label field full"><input type="checkbox" required>El beneficiario recibió el fondo completo y confirmé esta entrega.</label></div><p id="payout-error" class="form-error"></p><div class="form-actions"><button type="submit" class="button primary">Confirmar entrega registrada</button></div></form>`);}
function fundModal(){const g=group(),tot=groupTotals(g);showModal(`<h2>Registrar uso de las multas</h2><p>Fondo disponible: <strong>${money(tot.finePaid-tot.fineUsed)}</strong><br>Destino acordado: ${escape(g.fundDestination)}</p><form id="fund-form"><div class="field"><label for="fund-amount">Monto utilizado (Bs)</label><input id="fund-amount" name="amount" type="number" min="0.01" step="0.01" required></div><br><div class="field"><label for="fund-reason">Destino, beneficiarios y motivo</label><textarea id="fund-reason" name="reason" minlength="5" maxlength="300" required></textarea></div><br><label class="check-label"><input type="checkbox" required>El grupo acordó este uso y el dinero ya se entregó o utilizó.</label><p class="form-error" id="fund-error"></p><div class="form-actions"><button type="submit" class="button primary">Guardar uso del fondo</button></div></form>`);}
function drawWheel(g,rotation=0){const canvas=$('wheel');if(!canvas)return;const ctx=canvas.getContext('2d');const remaining=g.people.filter(p=>!g.order.includes(p.id));const entries=remaining.length?remaining.map(p=>p.name):['Todos tienen','su turno','Cuentas claras','Ahorro juntos','Confianza','Pasanaku'];const colors=['#afd1ba','#e9c18c','#b4c8df','#c5b6da','#dfab9f','#d2d9a5','#91c4bd','#e3c9d1'];const arc=2*Math.PI/entries.length;ctx.clearRect(0,0,900,900);ctx.save();ctx.translate(450,450);ctx.rotate(rotation);entries.forEach((name,i)=>{const start=i*arc-Math.PI/2;ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,450,start,start+arc);ctx.closePath();ctx.fillStyle=colors[i%colors.length];ctx.fill();ctx.strokeStyle='#ffffff80';ctx.lineWidth=2;ctx.stroke();if(entries.length>50)return;ctx.save();ctx.rotate(start+arc/2);ctx.font=`600 ${entries.length>20?16:entries.length>12?20:27}px Arial`;ctx.fillStyle='#2a4e3b';ctx.textAlign='right';ctx.textBaseline='middle';let label=name;while(ctx.measureText(label).width>290&&label.length>1)label=label.slice(0,-1);if(label!==name)label=label.slice(0,-1)+'…';ctx.fillText(label,405,0);ctx.restore();});ctx.restore();}
function spin(){const g=group();if(spinning||g.pending)return;const remaining=g.people.filter(p=>!g.order.includes(p.id));if(!remaining.length)return;const index=chooseIndex(remaining,g.order.length);if(!change(()=>{g.pending={person:remaining[index].id,at:new Date().toISOString()};audit(g,`Resultado del turno ${g.order.length+1} fijado: ${remaining[index].name}. Pendiente de aceptar.`);}))return;spinning=true;render();const target=(2*Math.PI-(index+.5)*2*Math.PI/remaining.length)%(2*Math.PI),from=angle,to=from+10*Math.PI+((target-from%(2*Math.PI)+2*Math.PI)%(2*Math.PI));const start=performance.now(),duration=matchMedia('(prefers-reduced-motion: reduce)').matches?0:3400;function frame(now){const t=duration?Math.min((now-start)/duration,1):1;angle=from+(to-from)*(1-(1-t)**4);drawWheel(g,angle);if(t<1)requestAnimationFrame(frame);else{spinning=false;angle=target;render();showPending();}}requestAnimationFrame(frame);}
function showPending(){const g=group();if(!g?.pending)return;const p=g.periods[g.order.length];showModal(`<div class="result"><div class="result-icon">✦</div><div class="eyebrow">TURNO ${g.order.length+1} · ${escape(formatDate(p.date))}</div><h2>${escape(person(g,g.pending.person).name)}</h2><p>Este resultado ya está guardado. Al aceptar se asignará la fecha y el nombre saldrá de la ruleta.</p>${button('Aceptar y asignar turno '+icon('arrow'),'accept','primary')}</div>`,true);}
function downloadBackup(){const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`pasanaku-respaldo-${localNow().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function validateBackup(data){if(!data||data.schema!==2||!Array.isArray(data.groups)||data.groups.length>200)throw Error('El archivo no es un respaldo compatible.');const ids=new Set();for(const g of data.groups){if(!validId(g.id)||ids.has(g.id))throw Error('Identificadores de grupo inválidos.');ids.add(g.id);for(const k of ['name','admin','time','fundDestination','agreement','createdAt'])if(typeof g[k]!=='string')throw Error('Faltan acuerdos del grupo.');if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(g.time))throw Error('Hora límite inválida.');if(!Number.isSafeInteger(g.amount)||g.amount<=0||g.amount>100000000||!Number.isSafeInteger(g.fine)||g.fine<0||g.fine>100000000)throw Error('Los montos del respaldo no son válidos.');if(!['monthly','weekly','custom'].includes(g.frequency)||!Number.isInteger(g.interval)||g.interval<1||g.interval>365)throw Error('Frecuencia inválida.');for(const k of ['people','periods','payments','order','waivers','fundUses','audit'])if(!Array.isArray(g[k]))throw Error('El respaldo está incompleto.');if(g.people.length<2||g.people.length>100||g.periods.length!==g.people.length)throw Error('Participantes o calendario inválidos.');const people=new Set(g.people.map(p=>p.id)),periods=new Set(g.periods.map(p=>p.id));if(people.size!==g.people.length||periods.size!==g.periods.length||g.people.some(p=>!validId(p.id)||typeof p.name!=='string'||!p.name.trim()))throw Error('Participantes inválidos.');if(new Set(g.order).size!==g.order.length||g.order.some(id=>!people.has(id)))throw Error('Orden de sorteo inválido.');if(g.pending&&(!people.has(g.pending.person)||g.order.includes(g.pending.person)))throw Error('Resultado pendiente inválido.');for(const [i,p]of g.periods.entries()){if(!validId(p.id)||!Number.isFinite(deadline(p))||!/^\d{4}-\d{2}-\d{2}$/.test(p.date)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(p.time)||p.person!==(g.order[i]||null))throw Error('Turnos inválidos.');if(p.payout&&(!Number.isFinite(Date.parse(p.payout.at))||p.payout.amount!==g.amount*g.people.length))throw Error('Desembolso inválido.');}for(const r of g.payments){if(!validId(r.id)||!people.has(r.person)||!periods.has(r.period)||!Number.isFinite(Date.parse(r.at))||!Number.isSafeInteger(r.principal)||r.principal<0||!Number.isSafeInteger(r.fine)||r.fine<0||typeof r.method!=='string'||typeof r.reference!=='string')throw Error('Registro de pago inválido.');}if(new Set(g.payments.map(r=>r.id)).size!==g.payments.length)throw Error('Pagos duplicados.');for(const w of g.waivers)if(!validId(w.id)||!people.has(w.person)||!periods.has(w.period)||typeof w.reason!=='string')throw Error('Condonación inválida.');for(const r of g.fundUses)if(!validId(r.id)||!Number.isSafeInteger(r.amount)||r.amount<=0||typeof r.reason!=='string'||!Number.isFinite(Date.parse(r.at)))throw Error('Uso de fondo inválido.');for(const a of g.audit)if(!validId(a.id)||typeof a.text!=='string'||!Number.isFinite(Date.parse(a.at)))throw Error('Historial inválido.');for(const p of g.periods){for(const who of g.people){const o=obligation(g,p,who);if(o.principal>g.amount||o.finePaid>o.fine)throw Error('Saldos de pagos inconsistentes.');}if(p.payout&&periodTotals(g,p).owed)throw Error('Hay una entrega con aportes faltantes.');}const t=groupTotals(g);if(t.finePaid<t.fineUsed)throw Error('El fondo de multas tiene saldo negativo.');}if((data.groups.length&&!ids.has(data.active))||(!data.groups.length&&data.active!==null))throw Error('El grupo activo no existe.');return true;}
async function cloudLoad(){const remote=await sync.previewRemote(),data=remote.data;if(!data){notify('La cuenta está vacía. El próximo cambio se guardará automáticamente.');return;}validateBackup(data);showModal(`<h2>Revisar la copia de Supabase</h2><p>Contiene ${data.groups.length} grupos. Cargarla reemplazará los datos de este dispositivo. Descarga primero una copia si tienes cambios locales pendientes.</p><div class="actions">${button('Descargar copia local','backup','secondary')}${button('Usar copia de Supabase','cloud-use')}</div>`);pendingCloud=remote;}
let pendingImport=null,pendingCloud=null;
document.addEventListener('click',async event=>{const route=event.target.closest('[data-view]');if(route){if(spinning)return notify('Espera a que termine el giro.');view=route.dataset.view;search='';render();window.scrollTo({top:0});return;}const control=event.target.closest('[data-action]');if(!control)return;const task=control.dataset.action,g=group();try{if(task==='create')createGroup();if(task==='turn'){periodId=control.dataset.id;view='payments';render();}if(task==='payment')paymentModal(control.dataset.person,control.dataset.period);if(task==='spin')spin();if(task==='pending')showPending();if(task==='accept'){if(g.pending&&change(()=>{const p=g.periods[g.order.length];p.person=g.pending.person;g.order.push(g.pending.person);audit(g,`Turno ${g.order.length} aceptado para ${person(g,g.pending.person).name}, fecha ${p.date}.`);g.pending=null;angle=0;},'Turno asignado.'))$('modal').close();}if(task==='report-all')openReport(g);if(task==='report-period')openReport(g,selected(g).id);if(task==='payout')payoutModal();if(task==='void-payment')reasonModal('Anular un registro','El movimiento seguirá visible. Sus montos dejarán de contar en el saldo. Si ya respaldó una entrega, no se podrá anular.','void',`data-id="${control.dataset.id}"`);if(task==='waive')reasonModal('Condonar una multa','Registra el acuerdo que justifica perdonar esta multa. Solo se permiten multas que aún no fueron cobradas.','waive',`data-person="${control.dataset.person}" data-period="${control.dataset.period}"`);if(task==='fund-use')fundModal();if(task==='backup')downloadBackup();if(task==='import')$('import-file').click();if(task==='restore'){if(pendingImport&&change(()=>{db=structuredClone(pendingImport);periodId=null;},'Datos cargados. Se guardarán automáticamente al conectar.')){pendingImport=null;$('modal').close();}}if(task==='cloud-use'){if(pendingCloud){sync.useRemote(pendingCloud);pendingCloud=null;$('modal').close();notify('Copia de Supabase recuperada.');}}if(task==='logout'){logout();sync.connectionChanged();render();notify('Sesión cerrada. La copia local sigue en este navegador.');}if(task==='cloud-probe'){control.disabled=true;await probeConnection();notify('Supabase responde correctamente. Inicia sesión para acceder a tus datos privados.');}if(task==='cloud-load'){control.disabled=true;await cloudLoad();}if(task==='cloud-push'||task==='sync-retry'){if(['conflict','auth'].includes(sync.status().kind)){view='settings';render();}else{control.disabled=true;await sync.reconcile();}}if(task==='delete-group'){showModal(`<h2>Eliminar grupo sin iniciar</h2><p>Se eliminará ${escape(g.name)} de esta copia. No contiene sorteos ni movimientos.</p>${button('Confirmar eliminación','delete-confirm','danger')}`);}if(task==='delete-confirm'){if(g.order.length||g.pending||g.payments.length||g.fundUses.length)throw Error('El grupo ya comenzó.');if(change(()=>{db.groups=db.groups.filter(x=>x.id!==g.id);db.active=db.groups[0]?.id||null;},'Grupo sin iniciar eliminado.'))$('modal').close();}}catch(error){notify(error.message);}finally{if(control.isConnected)control.disabled=false;}});
document.addEventListener('change',event=>{if(event.target.id==='frequency')$('interval-field').hidden=event.target.value!=='custom';if(event.target.id==='group-select'){if(spinning)return;change(()=>{db.active=event.target.value;periodId=null;});if(group()?.pending)showPending();}if(event.target.id==='period-select'){periodId=event.target.value;render();}});
document.addEventListener('input',event=>{if(event.target.id==='search'){search=event.target.value;$('payment-rows').innerHTML=paymentRows(group(),selected(group()));}});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,submit=form.querySelector('[type="submit"]');const errorNode=form.querySelector('.form-error');if(errorNode)errorNode.textContent='';if(submit)submit.disabled=true;try{if(form.id==='group-form')submitGroup(form);if(form.id==='payment-form')submitPayment(form);if(form.id==='reason-form')submitReason(form);if(form.id==='payout-form'){const g=group(),p=g.periods.find(p=>p.id===form.dataset.period),f=Object.fromEntries(new FormData(form)),at=new Date(f.at+':00-04:00').toISOString();if(Date.parse(at)>Date.now()+60000)throw Error('La entrega no puede estar en el futuro.');const amount=validatePayout(g,p);if(Date.parse(at)<Date.parse(p.date+'T00:00:00-04:00'))throw Error('La entrega no puede ser anterior a la fecha del turno.');const lastPayment=Math.max(...g.payments.filter(r=>!r.voided&&r.period===p.id&&r.principal).map(r=>Date.parse(r.at)));if(Date.parse(at)<lastPayment)throw Error('La entrega no puede ser anterior al último aporte recibido.');if(change(()=>{p.payout={amount,at,method:f.method,reference:f.reference.trim(),recordedAt:new Date().toISOString()};audit(g,`Entrega de ${money(amount)} registrada para ${person(g,p.person).name}. Turno ${g.periods.indexOf(p)+1}. Referencia: ${f.reference.trim()}`);},'Entrega del fondo registrada.'))$('modal').close();}if(form.id==='fund-form'){const g=group(),f=Object.fromEntries(new FormData(form)),amount=cents(f.amount),tot=groupTotals(g);if(!amount||amount>tot.finePaid-tot.fineUsed)throw Error('El monto supera el fondo disponible.');if(f.reason.trim().length<5)throw Error('Detalla el destino del dinero.');if(change(()=>{g.fundUses.push({id:uid(),amount,reason:f.reason.trim(),at:new Date().toISOString()});audit(g,`Uso de multas: ${money(amount)}. ${f.reason.trim()}`);},'Uso del fondo registrado.'))$('modal').close();}if(form.id==='config-form'){configure($('cloud-url').value,$('cloud-key').value);sync.connectionChanged();render();notify('Configuración guardada. Inicia sesión.');}if(form.id==='login-form'){await login($('email').value,$('password').value);sync.connectionChanged();render();notify('Sesión iniciada. Comprobando tus datos en Supabase…');}}catch(error){if(errorNode)errorNode.textContent=error.message;else notify(error.message);}finally{if(submit?.isConnected)submit.disabled=false;}});
$('import-file').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>10000000)throw Error('El respaldo supera los 10 MB permitidos.');const data=JSON.parse(await file.text());validateBackup(data);pendingImport=data;showModal(`<h2>Restaurar respaldo</h2><p>El archivo contiene ${data.groups.length} grupos. Reemplazará los datos locales actuales. Puedes descargar una copia antes de continuar.</p><div class="actions">${button('Respaldar datos actuales','backup','secondary')}${button('Restaurar estos datos','restore')}</div>`);}catch(error){notify('No se pudo cargar: '+error.message);}event.target.value='';});
function updateSyncUI() {
 const state=sync?.status()||{kind:'checking',message:'Comprobando guardado…'};
 if($('sync-label')) $('sync-label').textContent=state.message;
 if($('sync-banner')) $('sync-banner').dataset.state=state.kind;
 if($('sync-retry')) {$('sync-retry').hidden=!['error','offline','conflict','auth'].includes(state.kind);$('sync-retry').textContent=state.kind==='conflict'?'Revisar copias':state.kind==='auth'?'Iniciar sesión':'Reintentar';}
 if($('sync-detail')) $('sync-detail').textContent=state.message;
 if($('cloud-status')) $('cloud-status').textContent=state.message;
 if($('connection-label')) $('connection-label').textContent=state.kind==='saved'?'Guardado en Supabase':state.kind==='saving'?'Guardando…':cloudInfo().connected?'Guardado automático':'Guardado en este dispositivo';
}
sync=createAutoSync({
 initial:syncDoc,
 store:doc=>{const latest=localStorage.getItem(deviceKey);if(latest!==deviceRaw)throw Error('Otra pestaña cambió los datos. Recarga antes de continuar.');const raw=JSON.stringify(doc);localStorage.setItem(deviceKey,raw);deviceRaw=raw;},
 cloud:{scope:()=>cloudInfo().scope,read:readRemote,write:writeRemote},
 validate:validateBackup,
 onData:data=>{db=data;periodId=null;render();if(group()?.pending&&!$('modal').open)showPending();},
 onState:updateSyncUI,
 canReplace:()=>!storageProblem&&!$('modal').open&&!spinning,
 online:()=>navigator.onLine
});
window.addEventListener('storage',event=>{if([deviceKey,storageKey].includes(event.key)&&event.newValue){tabStale=true;sync.dispose();showModal('<h2>Los datos cambiaron en otra pestaña</h2><p>Recarga esta página para usar la copia más reciente antes de registrar otro movimiento.</p><button class="button primary" onclick="location.reload()">Recargar datos</button>',true);}});
window.addEventListener('online',()=>{if(!storageProblem)void sync.reconcile();});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!storageProblem)void sync.reconcile();});
window.addEventListener('beforeunload',event=>{const doc=sync.snapshot();if(doc.dirty&&(doc.owner||cloudInfo().connected)){event.preventDefault();event.returnValue='';}});
setInterval(()=>{if(!document.hidden&&cloudInfo().connected&&!storageProblem&&!tabStale)void sync.reconcile();},30000);
render();if(group()?.pending)showPending();if(!storageProblem)void sync.reconcile();
setInterval(()=>{if(!$('modal').open&&!spinning&&['overview','payments','fines','people'].includes(view)&&!document.activeElement?.matches('input,select,textarea'))render();},60000);
